(function(root){
 const clone=x=>JSON.parse(JSON.stringify(x)),month=t=>{const d=new Date(t);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')};
 const catalog={rice:{name:'香软米饭食材',icon:'🍚',price:600},egg:{name:'新鲜鸡蛋',icon:'🥚',price:300},tomato:{name:'红番茄',icon:'🍅',price:400},carrot:{name:'奶油胡萝卜',icon:'🥕',price:300},berry:{name:'鲜草莓',icon:'🍓',price:800},milk:{name:'鲜牛奶',icon:'🥛',price:600}};
 Object.values(catalog).forEach(i=>i.category='生鲜食材');
 const shelves={
 '生鲜食材':[['potato','土豆','🥔',400],['onion','洋葱','🧅',300],['broccoli','西兰花','🥦',600],['cabbage','小白菜','🥬',400],['corn','甜玉米','🌽',500],['mushroom','鲜蘑菇','🍄',600],['cucumber','黄瓜','🥒',400],['pepper','甜椒','🫑',500],['tofu','嫩豆腐','◻️',400],['pork','鲜猪肉','🥩',1800],['beef','牛肉','🥩',2800],['chicken','鸡胸肉','🍗',1600],['fish','鱼肉','🐟',2200],['shrimp','鲜虾','🦐',2600],['noodle','面条','🍜',500],['flour','低筋面粉','🌾',700],['butter','黄油','🧈',1200],['cheese','芝士','🧀',1200]],
 '水果零食':[['apple','脆甜苹果','🍎',600],['banana','香蕉','🍌',500],['orange','橙子','🍊',600],['grape','葡萄','🍇',1200],['peach','水蜜桃','🍑',900],['bread','吐司面包','🍞',1000],['croissant','可颂','🥐',1200],['cookie','黄油饼干','🍪',1500],['chocolate','巧克力','🍫',1800],['chips','薯片','🥔',800],['icecream','香草冰淇淋','🍦',1000],['cake','草莓小蛋糕','🍰',2200]],
 '饮品':[['water','矿泉水','💧',200],['tea','茉莉花茶','🍵',600],['coffee','拿铁咖啡','☕',1800],['juice','鲜橙汁','🧃',800],['soda','气泡水','🥤',600],['yogurt','原味酸奶','🥛',700],['cocoa','热可可','☕',1200],['peachtea','蜜桃乌龙','🧋',1400]],
 '日用清洁':[['tissue','柔软纸巾','🧻',1000],['soap','香皂','🧼',800],['shampoo','洗发水','🧴',3500],['bodywash','沐浴露','🧴',2800],['toothbrush','软毛牙刷','🪥',1200],['toothpaste','薄荷牙膏','🪥',1600],['towel','棉毛巾','🧺',1800],['detergent','洗衣液','🧴',3200],['dishsoap','洗洁精','🫧',1500],['trashbag','垃圾袋','🗑️',800]],
 '居家小物':[['mug','樱花马克杯','☕',2600],['notebook','方格笔记本','📓',1500],['pen','中性笔套装','🖊️',900],['umbrella','晴雨伞','☂️',3900],['slippers','居家拖鞋','🩴',2900],['candle','花香蜡烛','🕯️',2800],['bouquet','一束鲜花','💐',3500],['lunchbox','便当盒','🍱',3200]]};
 for(const [category,items]of Object.entries(shelves))for(const[id,name,icon,price]of items)catalog[id]={name,icon,price,category};
 const recipes={ricebowl:{name:'番茄蛋饭',icon:'🍲',need:{rice:1,egg:1,tomato:1}},soup:{name:'胡萝卜浓汤',icon:'🥣',need:{carrot:2,milk:1}},dessert:{name:'草莓牛乳',icon:'🍨',need:{berry:1,milk:1}},potatobeef:{name:'土豆炖牛肉',icon:'🥘',need:{potato:1,beef:1,onion:1}},chickenrice:{name:'鸡肉蔬菜饭',icon:'🍛',need:{rice:1,chicken:1,broccoli:1}},cornsoup:{name:'玉米浓汤',icon:'🥣',need:{corn:1,milk:1}},tofupot:{name:'番茄豆腐煲',icon:'🍲',need:{tomato:1,tofu:1,mushroom:1}},shrimpnoodle:{name:'鲜虾面',icon:'🍜',need:{shrimp:1,noodle:1,cabbage:1}},fishrice:{name:'香煎鱼饭',icon:'🍱',need:{fish:1,rice:1,cucumber:1}},porkpepper:{name:'甜椒炒肉',icon:'🥘',need:{pork:1,pepper:1,onion:1}},omelet:{name:'芝士蘑菇蛋卷',icon:'🍳',need:{egg:2,cheese:1,mushroom:1}},pancake:{name:'草莓松饼',icon:'🥞',need:{flour:1,egg:1,milk:1,berry:1}},buttercookie:{name:'手作黄油饼干',icon:'🍪',need:{flour:1,butter:1,egg:1}},veggienoodle:{name:'田园蔬菜面',icon:'🍜',need:{noodle:1,carrot:1,cabbage:1}},mashedpotato:{name:'奶香土豆泥',icon:'🥔',need:{potato:2,milk:1,butter:1}}};
 function normalize(w){return {...clone(w),accounts:clone(w.accounts||{}),kinCards:clone(w.kinCards||{}),inventory:clone(w.inventory||{}),orders:clone(w.orders||[]),roleTransfers:clone(w.roleTransfers||[])}}
 function account(w,id){return w.accounts?.[id]||{balance:1000000,ledger:[]}}
 function change(w,id,delta,entry){const a=clone(account(w,id)),n=a.balance+delta;if(!Number.isSafeInteger(n)||n<0)throw Error('角色余额不足或金额超出范围');a.balance=n;a.ledger.push({...entry,delta,balance:n});w.accounts[id]=a}
 function send(w,a,cents){if(a.type==='redpacket'&&cents>20000)throw Error('单个红包最多 200 元');const n=normalize(w);if(n.roleTransfers.some(x=>x.id===a.id))return n;if(a.direction==='user'){if(n.balance<cents)throw Error('零钱余额不足');n.balance-=cents;n.ledger.push({messageId:a.id,id:a.id,delta:-cents,balance:n.balance,type:a.type,peer:a.peer,note:a.note,createdAt:a.at});change(n,a.peerId,cents,{id:a.id,at:a.at,type:a.type,note:a.note})}else change(n,a.peerId,-cents,{id:a.id,at:a.at,type:a.type,note:a.note,status:'reserved'});n.roleTransfers.push({id:a.id,sender:a.peerId,status:a.direction==='user'?'sent':'reserved',cents});return n}
 function receive(w,a,cents){const n=normalize(w);if(n.ledger.some(x=>x.messageId===a.id))return n;const reserved=n.roleTransfers.find(x=>x.id===a.id&&x.status==='reserved');if(!reserved)change(n,a.peerId,-cents,{id:a.id,at:a.at,type:a.type,status:'sent'});else{if(reserved.cents!==cents||reserved.sender!==a.peerId)throw Error('卡片金额或出资者不一致');reserved.status='received'}if(!Number.isSafeInteger(n.balance+cents))throw Error('零钱金额超出范围');n.balance+=cents;n.ledger.push({id:a.id,messageId:a.id,delta:cents,balance:n.balance,type:a.type,peer:a.peer,note:a.note,createdAt:a.at});return n}
 function kin(w,a,cents){const n=normalize(w),old=n.kinCards[a.roleId];if(old?.offerId===a.id)return n;n.kinCards[a.roleId]={roleId:a.roleId,limit:cents,month:old?.month||month(a.at),spent:old?.spent||0,offerId:a.id,note:String(a.note||'').slice(0,80),at:a.at,active:true};return n}
 function available(w,id,at=Date.now()){const c=w.kinCards?.[id];if(!c?.active)return 0;return Math.max(0,Math.min(account(w,id).balance,c.limit-(c.month===month(at)?c.spent:0)))}
 function purchase(w,a){const item=catalog[a.item];if(!item||!Number.isInteger(a.quantity)||a.quantity<1||a.quantity>99)throw Error('请选择商品和 1–99 的数量');const n=normalize(w);if(n.orders.some(x=>x.id===a.id))return n;const total=item.price*a.quantity;if(a.pay==='self'){if(n.balance<total)throw Error('自己的零钱余额不足');n.balance-=total;n.ledger.push({id:a.id,messageId:a.id,type:'shopping',delta:-total,balance:n.balance,note:item.name,createdAt:a.at})}else{if(available(n,a.pay,a.at)<total)throw Error('亲属卡本月额度或出资角色余额不足');const card=n.kinCards[a.pay];if(card.month!==month(a.at)){card.month=month(a.at);card.spent=0}card.spent+=total;change(n,a.pay,-total,{id:a.id,at:a.at,type:'kin-shopping',note:item.name})}n.inventory[a.item]=(n.inventory[a.item]||0)+a.quantity;n.orders.push({id:a.id,item:a.item,quantity:a.quantity,total,pay:a.pay,at:a.at});return n}
 function cook(w,id){const r=recipes[id];if(!r)throw Error('请选择菜谱');const n=normalize(w);for(const [k,q]of Object.entries(r.need))if((n.inventory[k]||0)<q)throw Error('食材不足：'+catalog[k].name);for(const[k,q]of Object.entries(r.need))n.inventory[k]-=q;n.inventory['meal:'+id]=(n.inventory['meal:'+id]||0)+1;return n}
 function event(s,raw){const n=clone(s),audience=[...new Set(raw.audience||[])];n.events.push({id:raw.id,createdAt:raw.at,role:raw.speaker==='me'?'user':'assistant',speaker:raw.speaker||'system',content:String(raw.content).slice(0,6000),audience,private:!!raw.private});return n}
 function visible(s,roleId){return s.events.filter(e=>e.audience.includes(roleId))}
 function publicHistory(s,roleId,members){return visible(s,roleId).filter(e=>!e.private&&(!members||members.every(id=>e.audience.includes(id))))}
 function control(text){const match=String(text).match(/\[\[亲属卡\|(\d+(?:\.\d{1,2})?)\|([^\]\n]{0,80})\]\]/);if(!match)return {text};return {text:text.replace(match[0],'').trim()||'想把这张亲属卡交给你。',kin:{amount:match[1],note:match[2],status:'pending'}}}
 const api={clone,month,catalog,recipes,normalize,account,send,receive,kin,available,purchase,cook,event,visible,publicHistory,control};root.PalaisLiving=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
